import codecs
assert input() == 'ready'
for name in ('', 'missing', 'é' * 201):
    try:
        b'\xff'.decode('ascii', name)
    except LookupError as error:
        print(type(error).__name__, error.args)
    else:
        assert False
seen = []
def recover(error):
    seen.append((error.object, error.start, error.end))
    return ('?', -1)
codecs.register_error('resume', recover)
print(b'\xffZ'.decode('ascii', 'resume'), seen)

